-- Additional original SG practical scenarios. These are authored scenarios, not official exam questions.
INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-pack4-001','exam-sg','供应商账号离职后未关闭','第三方访问','standard','外包人员合同已结束，但其 VPN 账号仍可连接测试环境，最近还出现过登录记录。','最合适的处理是什么？','[{"id":"a","text":"等待账号自然过期"},{"id":"b","text":"立即按流程停用账号并核查访问日志、令牌及其他授权"},{"id":"c","text":"把账号交给新供应商继续使用"},{"id":"d","text":"只修改测试环境首页密码"}]','b','{"a":0,"b":100,"c":10,"d":10}','第三方人员离场应触发及时的权限撤销，并核查是否存在遗留令牌、共享凭据和异常访问。','authored'),
('sg-scenario-pack4-002','exam-sg','发现勒索软件告警','事件响应','intermediate','多个终端出现文件扩展名异常变化，EDR 同时报告疑似勒索软件行为。','首先应采取哪项行动？','[{"id":"a","text":"关闭所有日志以减轻系统负担"},{"id":"b","text":"按事件流程报告并由授权人员隔离受影响终端、保全证据"},{"id":"c","text":"立即删除所有备份"},{"id":"d","text":"在公司群里发送可疑样本供大家下载"}]','b','{"a":0,"b":100,"c":10,"d":10}','应尽快报告并依照预案隔离受影响资产、保护证据，避免扩散；不能随意销毁备份或传播样本。','authored'),
('sg-scenario-pack4-003','exam-sg','云存储链接权限过宽','クラウド利用','standard','项目文件夹被设置为“任何知道链接的人均可查看”，其中包含客户合同。','最恰当的改进是什么？','[{"id":"a","text":"保持现状，只要链接不公开就安全"},{"id":"b","text":"改为按业务需要授权给指定身份，检查现有访问记录并撤销过宽链接"},{"id":"c","text":"把链接发给所有员工备份"},{"id":"d","text":"只给文件改一个不容易猜的名称"}]','b','{"a":0,"b":100,"c":10,"d":10}','应采用最小权限和明确身份授权，并检查历史访问、撤销过宽共享；隐藏链接或改文件名不能代替访问控制。','authored'),
('sg-scenario-pack4-004','exam-sg','收到 MFA 连续推送','认证与访问控制','intermediate','员工没有尝试登录，却连续收到多次 MFA 批准请求。','正确的初始行动是什么？','[{"id":"a","text":"批准一次以停止通知"},{"id":"b","text":"拒绝请求，通过可信渠道报告并保护账号、检查登录记录"},{"id":"c","text":"将验证码发给自称 IT 的来电者"},{"id":"d","text":"关闭 MFA 功能"}]','b','{"a":0,"b":100,"c":10,"d":10}','未发起的 MFA 请求可能意味着凭据已泄露。拒绝请求，报告事件，并检查会话、密码和登录日志。','authored'),
('sg-scenario-pack4-005','exam-sg','备份任务显示成功但从未恢复','业务连续性','standard','关键系统每天备份成功，但团队从未验证备份能否在四小时内恢复。','如何验证备份有效性？','[{"id":"a","text":"只看成功日志即可"},{"id":"b","text":"进行定期恢复演练，验证数据完整性和实际恢复时间"},{"id":"c","text":"把唯一备份放在生产服务器同一磁盘"},{"id":"d","text":"每月删除旧备份但不做恢复测试"}]','b','{"a":0,"b":100,"c":10,"d":10}','备份任务成功不等于可恢复。应定期演练并验证数据完整性及 RTO/RPO 是否满足要求。','authored'),
('sg-scenario-pack4-006','exam-sg','紧急漏洞修复','漏洞管理','intermediate','互联网暴露的系统被发现存在可被利用的高危漏洞，供应商已发布修补程序。','如何兼顾速度与变更控制？','[{"id":"a","text":"等下个季度例行维护"},{"id":"b","text":"绕过记录直接修改生产环境"},{"id":"c","text":"启动紧急变更流程，评估风险、验证补丁、准备回滚并记录"},{"id":"d","text":"公开服务器地址请网友测试"}]','c','{"a":0,"b":0,"c":100,"d":10}','高危漏洞需快速处置，但仍应使用紧急变更流程，做好验证、审批、备份、回滚和记录。','authored'),
('sg-scenario-pack4-007','exam-sg','员工误发客户数据','个人信息保护','standard','员工把包含客户个人信息的附件发给了错误的外部收件人。','最恰当的初始处置是什么？','[{"id":"a","text":"删除发件箱记录后不再处理"},{"id":"b","text":"按组织流程立即报告并保留相关记录，由负责人评估影响和后续措施"},{"id":"c","text":"公开收件人姓名"},{"id":"d","text":"等对方回复后再决定是否报告"}]','b','{"a":0,"b":100,"c":10,"d":10}','误发事件应及时报告并保全记录，由责任部门评估影响、联系收件人和采取后续措施。','authored'),
('sg-scenario-pack4-008','exam-sg','管理员夜间修改权限','日志与监控','intermediate','审计日志显示管理员账号在非工作时间授予了新的高权限，但账号持有人否认操作。','调查时优先做什么？','[{"id":"a","text":"先删除日志避免误报"},{"id":"b","text":"保全日志与相关证据，核实登录会话和变更记录，并按流程遏制风险"},{"id":"c","text":"立即格式化所有服务器"},{"id":"d","text":"把日志上传到公开论坛"}]','b','{"a":0,"b":100,"c":10,"d":10}','应保护证据，核查身份、会话、来源和变更记录，并由授权人员采取适当遏制措施。','authored'),
('sg-scenario-pack4-009','exam-sg','开发人员要求生产数据','数据最小化','standard','开发人员希望把完整生产数据库复制到个人电脑用于排查测试问题。','应如何处理？','[{"id":"a","text":"直接复制以节省时间"},{"id":"b","text":"优先使用合成或脱敏数据，确有必要时按审批和安全控制流程处理"},{"id":"c","text":"把数据库发到个人邮箱"},{"id":"d","text":"只删除表名后就算匿名化"}]','b','{"a":0,"b":100,"c":10,"d":10}','开发测试应尽量使用合成或脱敏数据。生产数据使用需有正当目的、审批、最小范围和适当保护。','authored'),
('sg-scenario-pack4-010','exam-sg','疑似钓鱼邮件扩散','邮件安全','standard','同事收到仿冒公司云盘通知的邮件，要求输入密码；多人报告收到了相同邮件。','最合适的行动是什么？','[{"id":"a","text":"点击链接确认是否真实"},{"id":"b","text":"通过已知渠道核实，按流程报告并使用安全工具处置邮件"},{"id":"c","text":"转发给整个公司让大家自行判断"},{"id":"d","text":"只删除自己收到的邮件"}]','b','{"a":0,"b":100,"c":10,"d":10}','不要点击或输入凭据；通过可信渠道核实并报告，组织可按流程排查和阻断相同邮件。','authored'),
('sg-scenario-pack4-011','exam-sg','共享账号无法追责','身份管理','standard','多个管理员共用同一账号，发生配置变更后无法确认操作者。','最合适的改进是什么？','[{"id":"a","text":"继续共享并定期改密码"},{"id":"b","text":"为每人配置唯一身份，使用最小权限并记录审计日志"},{"id":"c","text":"把密码贴在机房门上"},{"id":"d","text":"取消所有管理员日志"}]','b','{"a":0,"b":100,"c":10,"d":10}','唯一身份、最小权限和可审计日志可提升责任追踪；共享账号会削弱可追溯性。','authored'),
('sg-scenario-pack4-012','exam-sg','员工离职未归还设备','资产管理','standard','员工离职后笔记本电脑尚未归还，设备上保存着企业资料。','正确的处置是什么？','[{"id":"a","text":"不处理，等员工想起来"},{"id":"b","text":"按离职流程联系回收设备，撤销凭据并评估远程锁定或擦除等授权措施"},{"id":"c","text":"在社交媒体公开员工信息"},{"id":"d","text":"只删除员工邮箱"}]','b','{"a":0,"b":100,"c":10,"d":10}','离职流程应覆盖设备、账号、密钥和资料；远程锁定或擦除须按组织授权流程执行。','authored'),
('sg-scenario-pack4-013','exam-sg','日志保存时间不足','日志管理','standard','安全事件发生两周后，团队发现关键系统日志只保留七天，调查证据已丢失。','最合理的改进是什么？','[{"id":"a","text":"永久保留所有日志且不做访问控制"},{"id":"b","text":"依据法规、风险和调查需求制定留存策略，并保护日志完整性和访问权限"},{"id":"c","text":"允许所有员工删除日志"},{"id":"d","text":"只在出事时临时开启日志"}]','b','{"a":0,"b":100,"c":10,"d":10}','日志留存应满足法规、业务和调查需求，同时限制访问、保护完整性并定期验证采集。','authored'),
('sg-scenario-pack4-014','exam-sg','防火墙规则过期','网络安全','standard','项目临时开放的入站端口在项目结束后仍对互联网开放。','应采取什么措施？','[{"id":"a","text":"保留规则以免影响未来项目"},{"id":"b","text":"复核业务需求，撤销过期规则并验证变更结果"},{"id":"c","text":"把端口改成另一个常见端口即可"},{"id":"d","text":"关闭所有监控"}]','b','{"a":0,"b":100,"c":10,"d":10}','网络规则应按最小开放原则管理，及时清理临时规则并验证业务与安全状态。','authored'),
('sg-scenario-pack4-015','exam-sg','RTO 与 RPO 混淆','业务连续性','standard','业务部门要求系统故障后两小时内恢复服务，并且最多只能丢失最近十五分钟的数据。','这两个目标分别是什么？','[{"id":"a","text":"RPO 两小时，RTO 十五分钟"},{"id":"b","text":"RTO 两小时，RPO 十五分钟"},{"id":"c","text":"两者都是 RTO"},{"id":"d","text":"两者都是 RPO"}]','b','{"a":0,"b":100,"c":10,"d":10}','RTO 是目标恢复时间；RPO 是可接受的数据恢复点/数据丢失时间范围。','authored'),
('sg-scenario-pack4-016','exam-sg','供应商未通知安全事件','供应链安全','intermediate','云服务供应商的合同没有明确安全事件通报时限，最近一次故障直到客户投诉才被发现。','最适合的改进是什么？','[{"id":"a","text":"只依赖供应商口头承诺"},{"id":"b","text":"通过供应商风险管理和合同机制明确事件通报、协作、证据与责任要求"},{"id":"c","text":"停止记录供应商问题"},{"id":"d","text":"把供应商账号设为永久管理员"}]','b','{"a":0,"b":100,"c":10,"d":10}','供应链安全需要明确安全事件通报、响应协作、责任分工、审计和退出机制。','authored'),
('sg-scenario-pack4-017','exam-sg','员工要求绕过审批','变更管理','standard','业务负责人要求直接修改生产数据库，理由是审批流程太慢，但变更影响尚未评估。','正确做法是什么？','[{"id":"a","text":"先修改再补单"},{"id":"b","text":"根据风险走正常或紧急变更流程，评估、审批、测试并准备回滚"},{"id":"c","text":"借用同事账号执行"},{"id":"d","text":"不留变更记录"}]','b','{"a":0,"b":100,"c":10,"d":10}','生产变更应按风险和正式流程执行；紧急情况可走紧急流程，但仍需记录和控制风险。','authored'),
('sg-scenario-pack4-018','exam-sg','移动设备丢失','终端安全','standard','员工在通勤途中遗失了已登录企业邮件的手机。','最合适的处置是什么？','[{"id":"a","text":"等待手机自动关机"},{"id":"b","text":"立即报告，按流程撤销会话和凭据，并使用已授权的设备管理措施"},{"id":"c","text":"在网上公开账号密码"},{"id":"d","text":"只更改手机壁纸"}]','b','{"a":0,"b":100,"c":10,"d":10}','丢失设备可能暴露会话和数据，应迅速报告、撤销会话/凭据，并依授权启用锁定或擦除。','authored'),
('sg-scenario-pack4-019','exam-sg','数据分类未标记','信息资产管理','standard','团队无法判断共享文件是否包含机密信息，因为文件没有分类标签或处理规则。','应如何改进？','[{"id":"a","text":"所有文件都公开共享"},{"id":"b","text":"依据数据敏感度和业务影响建立分类、标记及相应处理规则"},{"id":"c","text":"只按文件大小分类"},{"id":"d","text":"让每位员工自行决定是否加密"}]','b','{"a":0,"b":100,"c":10,"d":10}','信息分类应基于敏感度和影响，并与访问、存储、传输、保留和销毁控制对应。','authored'),
('sg-scenario-pack4-020','exam-sg','安全培训只统计出席','安全意识','standard','组织每年记录员工参加安全培训的人数，但钓鱼演练点击率持续偏高。','如何更有效评估培训？','[{"id":"a","text":"只增加签到表数量"},{"id":"b","text":"结合知识测验、行为指标和事件趋势评估效果，并针对薄弱点开展训练"},{"id":"c","text":"停止所有培训"},{"id":"d","text":"公开点名羞辱答错员工"}]','b','{"a":0,"b":100,"c":10,"d":10}','培训效果不能只看出席率，应结合知识、行为和事件指标，改进内容并避免惩罚式羞辱。','authored'),
('sg-scenario-pack4-021','exam-sg','加密密钥与数据同处','加密管理','intermediate','备份数据已加密，但密钥文件与备份存放在同一共享目录，且管理员都可读取。','最合适的改进是什么？','[{"id":"a","text":"把密钥改成更长的文件名"},{"id":"b","text":"分离密钥与数据的存储和权限，限制密钥访问并建立轮换与恢复流程"},{"id":"c","text":"把密钥写进公开文档"},{"id":"d","text":"取消访问日志"}]','b','{"a":0,"b":100,"c":10,"d":10}','密钥应与受保护数据分离，实施严格访问控制、审计、轮换和安全恢复管理。','authored'),
('sg-scenario-pack4-022','exam-sg','公开仓库意外提交密钥','开发安全','intermediate','开发人员把 API 密钥提交到公开代码仓库，随后立即删除了那一行代码。','还必须做什么？','[{"id":"a","text":"只删除提交即可"},{"id":"b","text":"立即撤销/轮换泄露密钥，检查访问日志和影响范围，并按事件流程处理历史提交"},{"id":"c","text":"把仓库改名"},{"id":"d","text":"要求所有用户忽略该提交"}]','b','{"a":0,"b":100,"c":10,"d":10}','密钥一旦泄露就应视为已暴露；删除代码不能使旧凭据失效，需轮换并调查使用情况。','authored'),
('sg-scenario-pack4-023','exam-sg','测试环境连接生产','环境隔离','standard','测试系统可以直接访问生产数据库，开发账号也拥有生产写权限。','最合理的改进是什么？','[{"id":"a","text":"保持连接以便调试"},{"id":"b","text":"隔离开发、测试和生产环境，限制网络路径和权限，并审计例外"},{"id":"c","text":"仅在测试环境更换颜色主题"},{"id":"d","text":"让开发人员共用生产管理员账号"}]','b','{"a":0,"b":100,"c":10,"d":10}','环境隔离、最小权限和经过审批的例外可降低测试误操作和横向移动风险。','authored'),
('sg-scenario-pack4-024','exam-sg','监控告警无人负责','安全运营','standard','安全监控平台持续产生告警，但没有明确值班人或升级流程，告警经常无人处理。','应优先完善什么？','[{"id":"a","text":"关闭所有低优先级告警"},{"id":"b","text":"定义告警分级、负责人、响应时限、升级路径和复盘机制"},{"id":"c","text":"让每个员工自行查看"},{"id":"d","text":"只在月底导出告警数量"}]','b','{"a":0,"b":100,"c":10,"d":10}','有效监控必须配合告警分级、责任人、响应 SLA、升级流程和持续改进。','authored'),
('sg-scenario-pack4-025','exam-sg','纸质机密文件随意丢弃','物理与媒体安全','standard','办公室把含客户信息的打印件直接放进普通垃圾桶。','正确的处理方式是什么？','[{"id":"a","text":"把纸张翻面再丢弃"},{"id":"b","text":"按信息分类使用安全销毁流程，并确保销毁过程符合组织要求"},{"id":"c","text":"拍照后上传公共云盘"},{"id":"d","text":"把垃圾桶移到走廊"}]','b','{"a":0,"b":100,"c":10,"d":10}','纸质和可移动介质也属于信息资产，应按敏感级别安全销毁并保留必要记录。','authored');
